#include <iostream>#include <string>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     string s;    cin >> s;    int n = (int)s.size();     int posAB = -1, posBA = -1;     for (int i = 0; i + 1 < n; i++) {        if (s[i] == 'A' && s[i + 1] == 'B') {            posAB = i;            break;        }    }     if (posAB != -1) {        for (int i = posAB + 2; i + 1 < n; i++) {            if (s[i] == 'B' && s[i + 1] == 'A') {                cout << "YES\n";                return 0;            }        }    }     for (int i = 0; i + 1 < n; i++) {        if (s[i] == 'B' && s[i + 1] == 'A') {            posBA = i;            break;        }    }     if (posBA != -1) {        for (int i = posBA + 2; i + 1 < n; i++) {            if (s[i] == 'A' && s[i + 1] == 'B') {                cout << "YES\n";                return 0;            }        }    }     cout << "NO\n";    return 0;}